281	    /**
282	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
283	     * stripped. When a leading {@code '+'} and country code are present they are kept;
284	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
285	     * is dropped from the national digits. The result must be a {@code '+'} followed
286	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
287	     * is returned to signal a bad request.
288	     */
289	    /**
290	     * Build the customer code for a newly created owner, formatted
291	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
292	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
293	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
294	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
295	     * with its last name. This identity carries no sequence number.
296	     */
297	    private String customerCode(Owner owner) {
298	        String region = owner.getLocality();
299	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
300	        return region + "-" + hash8;
301	    }
302	
303	    /**
304	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
305	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
306	     * treated as empty when {@code null}), already in their normalized forms.
307	     */
308	    private String customerCodeHash(String telephone, String lastName) {
309	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
310	        try {
311	            byte[] digest = MessageDigest.getInstance("SHA-256")
312	                .digest(key.getBytes(StandardCharsets.UTF_8));
313	            StringBuilder sb = new StringBuilder();
314	            for (int i = 0; i < 4; i++) {
315	                sb.append(String.format("%02X", digest[i]));
316	            }
317	            return sb.toString();
318	        }
319	        catch (NoSuchAlgorithmException e) {
320	            throw new IllegalStateException(e);
321	        }
322	    }
323	
324	    /**
325	     * Count the existing owners whose city matches the given one, compared after
326	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
327	     * cap: a city that already holds this many owners is at capacity.
328	     */
329	    private long countOwnersInCity(String city) {
330	        String normalizedCity = normalizeForHousehold(city);
331	        return this.clinicService.findAllOwners().stream()
332	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
333	            .count();
334	    }
335	
336	    /**
337	     * Count the existing owners whose registration date falls on the given day. Used to
338	     * enforce the per-day create limit: once this many owners have been registered today,
339	     * the day is at capacity and further creates are rejected.
340	     */
341	    private long countOwnersRegisteredOn(LocalDate day) {
342	        return this.clinicService.findAllOwners().stream()
343	            .filter(existing -> day.equals(existing.getRegistrationDate()))
344	            .count();
345	    }
346	
347	    /**
348	     * Roll a registration date forward to the next business day: a date falling on a
349	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
350	     * returned unchanged.
351	     */
352	    private LocalDate toBusinessDay(LocalDate date) {
353	        DayOfWeek dayOfWeek = date.getDayOfWeek();
354	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
355	            return date.plusDays(8 - dayOfWeek.getValue());
356	        }
357	        return date;
358	    }
359	
360	    /**
361	     * Find the existing owners that already belong to the same household as the given
362	     * computed household id. Because the household id is derived deterministically from
363	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
364	     * that last name and postcode.
365	     */
366	    private List<Owner> findHouseholdMembers(String householdId) {
367	        if (householdId == null) {
368	            return List.of();
369	        }
370	        return this.clinicService.findAllOwners().stream()
371	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
372	            .toList();
373	    }
374	
375	    /**
376	     * Find an existing owner that this new owner softly duplicates: one sharing the same
377	     * last name (compared case-insensitively after whitespace normalization) and the same
378	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
379	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
380	     * whose telephone equals the new owner's are excluded, as those are governed by the
381	     * hard-duplicate (identityKey) check rather than this soft match.
382	     */
383	    private Owner findPossibleDuplicate(Owner owner) {
384	        String postcode = owner.getPostcode();
385	        if (postcode == null) {
386	            return null;
387	        }
388	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
389	        String telephone = owner.getTelephone();
390	        return this.clinicService.findAllOwners().stream()
391	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
392	                && postcode.equals(existing.getPostcode())
393	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
394	            .min(java.util.Comparator.comparing(Owner::getId))
395	            .orElse(null);
396	    }
397	
398	    /**
399	     * Count the existing owners that already share both the given first and last
400	     * name, compared case-insensitively. Used to populate an owner's namesake count
401	     * at creation time, reflecting how many owners with the same name existed before
402	     * this one was created.
403	     */
404	    private int countNamesakes(String firstName, String lastName) {
405	        String normalizedFirstName = normalizeName(firstName);
406	        String normalizedLastName = normalizeName(lastName);
407	        return (int) this.clinicService.findAllOwners().stream()
408	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
409	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
410	            .count();
411	    }
412	
413	    private String normalizeName(String value) {
414	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
415	    }
416	
417	    /**
418	     * Build the deterministic identifier shared by all owners of one household: the first
419	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
420	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
421	     * name and postcode resolves to the same value regardless of creation order.
422	     */
423	    private String householdId(String lastName, String postcode) {
424	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
425	        try {
426	            byte[] digest = MessageDigest.getInstance("SHA-256")
427	                .digest(key.getBytes(StandardCharsets.UTF_8));
428	            StringBuilder sb = new StringBuilder();
429	            for (int i = 0; i < 6; i++) {
430	                sb.append(String.format("%02x", digest[i]));
431	            }
432	            return sb.toString();
433	        }
434	        catch (NoSuchAlgorithmException e) {
435	            throw new IllegalStateException(e);
436	        }
437	    }
438	
439	    private String normalizeForHousehold(String value) {
440	        if (value == null) {
441	            return "";
442	        }
443	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
444	    }
445	
446	    /** True when the email's domain is on the disposable-provider blocklist. */
447	    private boolean isDisposableEmailDomain(String email) {
448	        if (email == null) {
449	            return false;
450	        }
451	        int at = email.lastIndexOf('@');
452	        if (at < 0 || at == email.length() - 1) {
453	            return false;
454	        }
455	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
456	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
457	    }
458	
459	    private String normalizeTelephone(String telephone) {
460	        if (telephone == null) {
461	            return null;
462	        }
463	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
464	        String digits;
465	        if (cleaned.startsWith("+")) {
466	            digits = cleaned.substring(1);
467	        } else {
468	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
469	            digits = "61" + national;
470	        }
471	        if (!digits.matches("[0-9]{8,15}")) {
472	            return null;
473	        }
474	        if (!hasValidNationalLength(digits)) {
475	            return null;
476	        }
477	        return "+" + digits;
478	    }
479	
480	    /**
481	     * Validate the national-number length of an E.164 number (the digits, without the
482	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
483	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
484	     * codes without a known rule are accepted as-is.
485	     */
486	    private boolean hasValidNationalLength(String digits) {
487	        if (digits.startsWith("61")) {
488	            return digits.length() - 2 == 9;
489	        }
490	        if (digits.startsWith("1")) {
491	            return digits.length() - 1 == 10;
492	        }
493	        return true;
494	    }
