114	    /**
115	     * Set the owner's address, normalizing it to a canonical form so it is both
116	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
117	     * internal runs of whitespace are collapsed to a single space, the value is
118	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
119	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
120	     * left as-is.
121	     */
122	    public void setAddress(String address) {
123	        this.address = normalizeAddress(address);
124	    }
