126	    /**
127	     * Normalize an address string to its canonical form: trimmed, whitespace
128	     * collapsed, upper-cased, with common street-type abbreviations expanded.
129	     * Returns {@code null} for a {@code null} input; a value that is blank once
130	     * trimmed normalizes to the empty string.
131	     */
132	    public static String normalizeAddress(String address) {
133	        if (address == null) {
134	            return null;
135	        }
136	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
137	        if (collapsed.isEmpty()) {
138	            return "";
139	        }
140	        String[] tokens = collapsed.split(" ");
141	        StringBuilder sb = new StringBuilder();
142	        for (int i = 0; i < tokens.length; i++) {
143	            if (i > 0) {
144	                sb.append(' ');
145	            }
146	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
147	        }
148	        return sb.toString();
149	    }
