167	    /**
168	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
169	     * country code, a space, then the national digits grouped in threes and separated
170	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
171	     * North American country code ({@code '+1'}) is one digit; other country codes are
172	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
173	     * raw value unchanged when it is not a well-formed E.164 number.
174	     */
175	    public String getTelephoneDisplay() {
176	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
177	            return this.telephone;
178	        }
179	        String digits = this.telephone.substring(1);
180	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
181	        if (digits.length() <= countryCodeLength) {
182	            return this.telephone;
183	        }
184	        String countryCode = digits.substring(0, countryCodeLength);
185	        String national = digits.substring(countryCodeLength);
186	        StringBuilder sb = new StringBuilder("+").append(countryCode);
187	        for (int i = 0; i < national.length(); i += 3) {
188	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
189	        }
190	        return sb.toString();
191	    }
