249	    /**
250	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
251	     * is always valid (postcode is optional). When present, a postcode is valid if
252	     * the city has no known region, or if it is four digits falling within the
253	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
254	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
255	     */
256	    public boolean isPostcodeValidForCity() {
257	        if (this.postcode == null) {
258	            return true;
259	        }
260	        String region = CITY_REGION.get(this.city);
261	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
262	        if (range == null) {
263	            return true;
264	        }
265	        if (!this.postcode.matches("^[0-9]{4}$")) {
266	            return false;
267	        }
268	        int value = Integer.parseInt(this.postcode);
269	        return value >= range[0] && value <= range[1];
270	    }
