280	    /**
281	     * Return a single Luhn check digit (0-9) computed over the digits contained in
282	     * the owner's customer code, or {@code null} when the customer code is not set.
283	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
284	     * first, following the standard Luhn algorithm.
285	     */
286	    public Integer getCheckDigit() {
287	        if (this.customerCode == null) {
288	            return null;
289	        }
290	        int sum = 0;
291	        boolean doubleDigit = true;
292	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
293	            char c = this.customerCode.charAt(i);
294	            if (c < '0' || c > '9') {
295	                continue;
296	            }
297	            int digit = c - '0';
298	            if (doubleDigit) {
299	                digit *= 2;
300	                if (digit > 9) {
301	                    digit -= 9;
302	                }
303	            }
304	            sum += digit;
305	            doubleDigit = !doubleDigit;
306	        }
307	        return (10 - (sum % 10)) % 10;
308	    }
