335	    /**
336	     * Return the owner's membership points, the raw score from which the
337	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
338	     * email address is present, {@code 1} when the owner has no namesakes
339	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
340	     * more, and {@code 3} when the owner's tenure (days since the registration
341	     * date) exceeds {@code 365}.
342	     */
343	    public Integer getMembershipPoints() {
344	        int points = 0;
345	        boolean hasEmail = this.email != null && !this.email.isBlank();
346	        if (hasEmail) {
347	            points += 2;
348	        }
349	        if (this.namesakeCount != null && this.namesakeCount == 0) {
350	            points += 1;
351	        }
352	        if (this.householdSize != null && this.householdSize >= 3) {
353	            points += 2;
354	        }
355	        if (this.registrationDate != null
356	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
357	            points += 3;
358	        }
359	        return points;
360	    }
