362	    /**
363	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
364	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
365	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
366	     * {@code 4} for {@code 6} or more.
367	     */
368	    public Integer getMembershipLevel() {
369	        int points = getMembershipPoints();
370	        if (points >= 6) {
371	            return 4;
372	        }
373	        if (points >= 4) {
374	            return 3;
375	        }
376	        if (points >= 2) {
377	            return 2;
378	        }
379	        return 1;
380	    }
