433	     * Return the owner's locality (region), preferring the postcode: when the
434	     * postcode is present and falls within a known region's inclusive range
435	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
436	     * region is returned. Otherwise the value falls back to the fixed
437	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
438	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
439	     * table. This yields the same region for known cities but disambiguates
440	     * cities that share a name.
441	     */
442	    public String getLocality() {
443	        String regionFromPostcode = regionForPostcode();
444	        if (regionFromPostcode != null) {
