450	    /**
451	     * Look up the region whose inclusive postcode range contains this owner's
452	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
453	     * known range.
454	     */
455	    private String regionForPostcode() {
456	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
457	            return null;
458	        }
459	        int value = Integer.parseInt(this.postcode);
460	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
461	            int[] range = entry.getValue();
462	            if (value >= range[0] && value <= range[1]) {
463	                return entry.getKey();
464	            }
465	        }
466	        return null;
467	    }
